if (bit < wnd->zone_end && bit + bits0 > wnd->zone_bit) {
	size_t zbit = max(bit, wnd->zone_bit);
	size_t zend = min(bit + bits0, wnd->zone_end);

	if (zbit > bit)
		wnd_add_free_ext(wnd, bit, zbit - bit, false);

	if (zend < bit + bits0)
		wnd_add_free_ext(wnd, zend, bit + bits0 - zend, false);
} else {
	wnd_add_free_ext(wnd, bit, bits0, false);
}

